const LEVEL_MAP = new Map(MASTER_HOUSES.map(h => [h.level, h]));

export function lookupHouseByLevel(level) {
  const lv = Number(level);
  return LEVEL_MAP.get(lv) || MASTER_HOUSES[0];
}

